package dev.industrialtechnology.builder;

import java.util.*;
import org.junit.Test;
import static org.junit.Assert.*;
import dev.industrialtechnology.builder.client.WheelLayout;
import io.netty.buffer.Unpooled;
import io.netty.buffer.ByteBuf;

public class BuildShapeTest {
    private Set<BuildPos> points(BuildMode mode,boolean hollow,BuildPos a,BuildPos b){BuildShape shape=new BuildShape(mode,hollow,a,b);Set<BuildPos> result=new HashSet<BuildPos>();while(shape.hasNext()){BuildPos p=shape.next();if(p!=null)assertTrue("duplicate",result.add(p));}assertEquals(shape.candidates,shape.visited());return result;}
    @Test public void allModesProduceTheSingleCellForCoincidentPoints(){BuildPos a=new BuildPos(3,64,-5);for(BuildMode m:BuildMode.values())for(boolean hollow:new boolean[]{false,true})assertEquals(Collections.singleton(a),points(m,hollow,a,a));}
    @Test public void boxesWallsFloorsAndFramesHaveExactCounts(){BuildPos a=new BuildPos(0,64,0),b=new BuildPos(2,66,2);assertEquals(27,points(BuildMode.BOX,false,a,b).size());assertEquals(26,points(BuildMode.BOX,true,a,b).size());assertEquals(20,points(BuildMode.FRAME,false,a,b).size());assertEquals(9,points(BuildMode.WALL,false,a,b).size());assertEquals(9,points(BuildMode.FLOOR,false,a,b).size());assertEquals(3,points(BuildMode.LINE,false,a,b).size());}
    @Test public void diagonalLinesIncludeBothEndpointsWithoutGapsAndReverseExactly(){BuildPos a=new BuildPos(-8,62,3),b=new BuildPos(5,70,-4);Set<BuildPos> forward=points(BuildMode.DIAGONAL_LINE,false,a,b);assertEquals(14,forward.size());assertTrue(forward.contains(a)&&forward.contains(b));assertEquals(forward,points(BuildMode.DIAGONAL_LINE,false,b,a));}
    @Test public void slopesAndDiagonalWallsFollowTheChosenSpan(){BuildPos a=new BuildPos(0,64,0),b=new BuildPos(4,68,2);Set<BuildPos> slope=points(BuildMode.SLOPE_FLOOR,false,a,b);assertEquals(15,slope.size());for(BuildPos p:slope)assertEquals(64+p.x,p.y);assertEquals(25,points(BuildMode.DIAGONAL_WALL,false,a,b).size());}
    @Test public void roundShapesAreSymmetricAndHollowShapesHaveNoInterior(){BuildPos a=new BuildPos(0,64,0);Set<BuildPos> ball=points(BuildMode.SPHERE,false,a,new BuildPos(2,64,0));assertEquals(33,ball.size());assertEquals(26,points(BuildMode.SPHERE,true,a,new BuildPos(2,64,0)).size());for(BuildPos p:ball)assertTrue(ball.contains(new BuildPos(-p.x,128-p.y,-p.z)));assertEquals(13,points(BuildMode.CIRCLE,false,a,new BuildPos(2,64,0)).size());assertEquals(8,points(BuildMode.CIRCLE,true,a,new BuildPos(2,64,0)).size());assertEquals(15,points(BuildMode.CYLINDER,false,a,new BuildPos(1,66,0)).size());assertEquals(14,points(BuildMode.CYLINDER,true,a,new BuildPos(1,66,0)).size());}
    @Test public void cursorsAreFiniteAndRejectUnsafeBounds(){BuildShape s=new BuildShape(BuildMode.SPHERE,true,new BuildPos(0,64,0),new BuildPos(16,64,0));int visits=0;while(s.hasNext()){s.next();visits++;}assertEquals(35937,visits);assertThrows(IllegalArgumentException.class,()->new BuildShape(BuildMode.LINE,false,new BuildPos(0,64,0),new BuildPos(33,64,0)));assertThrows(IllegalArgumentException.class,()->new BuildShape(BuildMode.SPHERE,false,new BuildPos(0,1,0),new BuildPos(2,1,0)));assertThrows(IllegalArgumentException.class,()->new BuildShape(BuildMode.BOX,false,new BuildPos(Integer.MIN_VALUE,64,0),new BuildPos(Integer.MAX_VALUE,64,0)));}
    @Test public void everyRadialSectorAndCenterDeadZoneAreDeterministic(){for(int i=0;i<12;i++){double a=WheelLayout.angle(i,12);assertEquals(i,WheelLayout.sector(Math.cos(a)*70,Math.sin(a)*70,38,100,12));}assertEquals(-1,WheelLayout.sector(0,0,38,100,12));assertEquals(-1,WheelLayout.sector(101,0,38,100,12));}
    @Test public void networkFrameIsFixedAndMalformedFramesAreIgnored(){ByteBuf b=Unpooled.buffer();try{BuildCommand c=new BuildCommand(BuildCommand.AIR_END,5,BuildMode.BOX,true,new BuildPos(-8,128,10));c.toBytes(b);assertEquals(16,b.readableBytes());BuildCommand copy=new BuildCommand();copy.fromBytes(b);assertEquals(c.x,copy.x);assertEquals(c.y,copy.y);assertEquals(c.z,copy.z);assertEquals(5,copy.slot);assertTrue(copy.hollow);assertEquals(BuildMode.BOX.ordinal(),copy.mode);}finally{b.release();}ByteBuf shortFrame=Unpooled.buffer();try{shortFrame.writeByte(0);BuildCommand invalid=new BuildCommand();invalid.fromBytes(shortFrame);assertEquals(-1,invalid.action);}finally{shortFrame.release();}}
}
